import os, sys
sys.path.insert(0, os.getcwd())
import sqlite3
from src.repository import initialize, balance
from src.service import transfer
from src.events import Recorder


def fresh():
    c = sqlite3.connect(":memory:")
    initialize(c)
    c.executemany("INSERT INTO accounts VALUES (?, ?)", [("a", 100), ("b", 20)])
    c.commit()
    return c


def ledger(c):
    return c.execute("SELECT * FROM ledger").fetchall()


def expect_invalid(args):
    c = fresh(); p = Recorder()
    try:
        transfer(c, p, *args(c))
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError")
    assert (balance(c, "a"), balance(c, "b")) == (100, 20)
    assert ledger(c) == [] and p.events == []


for amt in [0, -1, True, False, 1.0, "5", None, 101]:
    expect_invalid(lambda c, amt=amt: ("a", "b", amt))
expect_invalid(lambda c: ("a", "a", 5))
expect_invalid(lambda c: ("x", "b", 5))
expect_invalid(lambda c: ("a", "x", 5))


class FailingConn:
    """Wraps a connection; raises on the Nth execute or on commit."""
    def __init__(self, inner, fail_at=None, fail_commit=False):
        self.inner, self.n, self.fail_at, self.fail_commit = inner, 0, fail_at, fail_commit
        self.rolled_back = False
    def execute(self, *a):
        self.n += 1
        if self.n == self.fail_at:
            raise sqlite3.OperationalError("boom")
        return self.inner.execute(*a)
    def commit(self):
        if self.fail_commit:
            raise sqlite3.OperationalError("commit boom")
        return self.inner.commit()
    def rollback(self):
        self.rolled_back = True
        return self.inner.rollback()


for kwargs in [dict(fail_at=1), dict(fail_at=2), dict(fail_at=3), dict(fail_commit=True)]:
    c = fresh(); p = Recorder()
    fc = FailingConn(c, **kwargs)
    try:
        transfer(fc, p, "a", "b", 10)
    except sqlite3.OperationalError:
        pass
    else:
        raise AssertionError("expected db failure")
    assert fc.rolled_back
    assert (balance(c, "a"), balance(c, "b")) == (100, 20), kwargs
    assert ledger(c) == [] and p.events == [], kwargs


class BrokenPublisher:
    def publish(self, event):
        raise RuntimeError("publish down")


c = fresh()
try:
    transfer(c, BrokenPublisher(), "a", "b", 10)
except RuntimeError:
    pass
else:
    raise AssertionError("publication failure should propagate")
assert (balance(c, "a"), balance(c, "b")) == (90, 30)
assert ledger(c) == [("a", "b", 10)]

c = fresh(); p = Recorder()
transfer(c, p, "a", "b", 100)
assert (balance(c, "a"), balance(c, "b")) == (0, 120)
assert ledger(c) == [("a", "b", 100)] and p.events == [{"source": "a", "target": "b", "amount": 100}]
print("transfer checks passed")
